import { Upload } from "./Upload";
import "./Upload.css";

<Upload
  speed={50}
  bounce={40}
  corner={16}
/>

notes:
/* THE BOX INHALES. A file held over it is answered before it
   is let go: a touch bigger, the dashed edge in the signal
   colour and marching, the arrow lifting toward the hand. */
.zone[data-over] { scale: 1.03; }
.zone[data-over] rect { stroke: var(--signal); animation: march 700ms linear infinite; }
@keyframes march { to { stroke-dashoffset: -22; } }

/* the files are part of the block: an ordinary pointer drag,
   hit-tested against the box on every move */
over = inside(zone, pointer) && idle;

/* the bar: uneven on purpose — a bar that climbs at a steady
   rate reads as a timer, not an upload */
p += (dt / secs) * (0.4 + Math.random() * 1.2);
